import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#define TILE_M 32
#define TILE_N 32
#define TILE_K 32

// FP16 GEMM kernel: C = A * B
// A: (M x K), B: (K x N), C: (M x N)
__global__ void gemm_kernel(const half* __restrict__ A,
                            const half* __restrict__ B,
                            half* __restrict__ C,
                            int M, int N, int K) {
    __shared__ half As[TILE_M][TILE_K];
    __shared__ half Bs[TILE_K][TILE_N];

    int row = blockIdx.y * TILE_M + threadIdx.y; // M dimension
    int col = blockIdx.x * TILE_N + threadIdx.x; // N dimension

    float acc = 0.0f;

    // Loop over K dimension in tiles
    for (int t = 0; t < (K + TILE_K - 1) / TILE_K; ++t) {
        // Load A tile
        int a_row = row;
        int a_col = t * TILE_K + threadIdx.x;
        if (a_row < M && a_col < K) {
            As[threadIdx.y][threadIdx.x] = A[a_row * K + a_col];
        } else {
            As[threadIdx.y][threadIdx.x] = __float2half(0.0f);
        }

        // Load B tile
        int b_row = t * TILE_K + threadIdx.y;
        int b_col = col;
        if (b_row < K && b_col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[b_row * N + b_col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = __float2half(0.0f);
        }

        __syncthreads();

        // Compute partial product
        #pragma unroll
        for (int k = 0; k < TILE_K; ++k) {
            acc += __half2float(As[threadIdx.y][k]) *
                   __half2float(Bs[k][threadIdx.x]);
        }

        __syncthreads();
    }

    // Write result
    if (row < M && col < N) {
        C[row * N + col] = __float2half(acc);
    }
}

// C++ launcher
void launch_gemm(torch::Tensor A,
                 torch::Tensor B,
                 torch::Tensor C) {
    const int M = A.size(0);
    const int K = A.size(1);
    const int N = B.size(1);

    const dim3 block(TILE_N, TILE_M);
    const dim3 grid((N + TILE_N - 1) / TILE_N,
                    (M + TILE_M - 1) / TILE_M);

    const half* a_ptr = reinterpret_cast<const half*>(A.data_ptr<at::Half>());
    const half* b_ptr = reinterpret_cast<const half*>(B.data_ptr<at::Half>());
    half* c_ptr = reinterpret_cast<half*>(C.data_ptr<at::Half>());

    gemm_kernel<<<grid, block, 0, at::cuda::getCurrentCUDAStream()>>>(
        a_ptr, b_ptr, c_ptr, M, N, K);
}

// Bindings
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("launch_gemm", &launch_gemm, "Launch FP16 GEMM kernel");
}
'''

# Compile the inline extension
gemm_ext = load_inline(name='gemm_ext',
                       cpp_sources='',
                       cuda_sources=src,
                       functions=['launch_gemm'],
                       verbose=False)

def _gemm_forward(A: torch.Tensor, B: torch.Tensor, C: torch.Tensor):
    """
    Wrapper that calls the compiled CUDA kernel.
    All tensors must be contiguous half tensors on the same CUDA device.
    """
    if not (A.is_cuda and B.is_cuda and C.is_cuda):
        raise RuntimeError("All tensors must be on CUDA")
    if not (A.dtype == B.dtype == C.dtype == torch.float16):
        raise RuntimeError("All tensors must be torch.float16")
    gemm_ext.launch_gemm(A, B, C)

class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model.
    Performs C = A @ B using a custom FP16 CUDA kernel.
    """
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # Ensure half precision and contiguous layout
        A_h = A.to(dtype=torch.float16, device='cuda', non_blocking=True).contiguous()
        B_h = B.to(dtype=torch.float16, device='cuda', non_blocking=True).contiguous()

        M, K = A_h.shape
        K2, N = B_h.shape
        if K != K2:
            raise RuntimeError(f"Incompatible shapes: A {A_h.shape}, B {B_h.shape}")

        C = torch.empty((M, N), dtype=torch.float16, device='cuda')
        _gemm_forward(A_h, B_h, C)
        return C
